// 6-DOF Robotic Manipulator Telemetry Ingestion & Dynamics Normalizer
const input = $input.first()?.json || {};
const body = input.body || input;

// Industrial Multi-Scenario Telemetry Profiles for 6-DOF Cobot (UR10e / KUKA iiwa standard)
const SCENARIOS = {
  critical_collision: {
    robot_id: "ROBOT-UR10E-CELL-04",
    joint_data: [
      { joint: 1, angle_cmd_deg: 45.0, angle_meas_deg: 45.02, torque_meas_nm: 24.5, current_a: 5.2, temp_c: 44.1, imu_accel_g: 0.18 },
      { joint: 2, angle_cmd_deg: -80.0, angle_meas_deg: -79.94, torque_meas_nm: 68.2, current_a: 11.4, temp_c: 56.3, imu_accel_g: 0.32 },
      { joint: 3, angle_cmd_deg: 115.0, angle_meas_deg: 111.80, torque_meas_nm: 112.4, current_a: 19.8, temp_c: 62.0, imu_accel_g: 0.85 },
      { joint: 4, angle_cmd_deg: -35.0, angle_meas_deg: -34.98, torque_meas_nm: 18.0, current_a: 4.1, temp_c: 42.5, imu_accel_g: 0.22 },
      { joint: 5, angle_cmd_deg: 90.0, angle_meas_deg: 86.40, torque_meas_nm: 89.6, current_a: 16.5, temp_c: 59.8, imu_accel_g: 0.74 },
      { joint: 6, angle_cmd_deg: 0.0, angle_meas_deg: 0.05, torque_meas_nm: 8.5, current_a: 2.1, temp_c: 38.2, imu_accel_g: 0.15 }
    ],
    expected_model_torques_nm: [23.0, 65.0, 38.0, 16.0, 14.0, 7.5],
    tcp_speed_m_s: 0.02,
    vibration_window_g: [0.35, 0.42, 0.95, 1.25, 0.88]
  },
  critical_harmonic_wear: {
    robot_id: "ROBOT-UR10E-CELL-04",
    joint_data: [
      { joint: 1, angle_cmd_deg: 30.0, angle_meas_deg: 29.98, torque_meas_nm: 22.0, current_a: 4.8, temp_c: 43.0, imu_accel_g: 0.20 },
      { joint: 2, angle_cmd_deg: -65.0, angle_meas_deg: -64.85, torque_meas_nm: 58.0, current_a: 10.2, temp_c: 54.0, imu_accel_g: 0.40 },
      { joint: 3, angle_cmd_deg: 95.0, angle_meas_deg: 93.65, torque_meas_nm: 44.0, current_a: 11.2, temp_c: 58.5, imu_accel_g: 1.95 },
      { joint: 4, angle_cmd_deg: -20.0, angle_meas_deg: -19.95, torque_meas_nm: 15.0, current_a: 3.8, temp_c: 41.0, imu_accel_g: 0.30 },
      { joint: 5, angle_cmd_deg: 45.0, angle_meas_deg: 44.92, torque_meas_nm: 16.5, current_a: 4.0, temp_c: 42.0, imu_accel_g: 0.25 },
      { joint: 6, angle_cmd_deg: 0.0, angle_meas_deg: 0.02, torque_meas_nm: 7.0, current_a: 2.0, temp_c: 37.0, imu_accel_g: 0.15 }
    ],
    expected_model_torques_nm: [21.5, 56.0, 42.0, 14.5, 15.8, 6.8],
    tcp_speed_m_s: 0.85,
    vibration_window_g: [1.45, 1.88, 2.15, 1.92, 1.76]
  },
  warning_thermal_overload: {
    robot_id: "ROBOT-UR10E-CELL-04",
    joint_data: [
      { joint: 1, angle_cmd_deg: 40.0, angle_meas_deg: 40.02, torque_meas_nm: 25.0, current_a: 5.5, temp_c: 48.0, imu_accel_g: 0.22 },
      { joint: 2, angle_cmd_deg: -70.0, angle_meas_deg: -69.96, torque_meas_nm: 69.5, current_a: 15.8, temp_c: 78.4, imu_accel_g: 0.38 },
      { joint: 3, angle_cmd_deg: 100.0, angle_meas_deg: 99.93, torque_meas_nm: 46.0, current_a: 14.2, temp_c: 76.2, imu_accel_g: 0.35 },
      { joint: 4, angle_cmd_deg: -30.0, angle_meas_deg: -29.98, torque_meas_nm: 17.0, current_a: 4.2, temp_c: 46.0, imu_accel_g: 0.20 },
      { joint: 5, angle_cmd_deg: 60.0, angle_meas_deg: 59.97, torque_meas_nm: 18.0, current_a: 4.6, temp_c: 47.0, imu_accel_g: 0.24 },
      { joint: 6, angle_cmd_deg: 10.0, angle_meas_deg: 10.01, torque_meas_nm: 8.0, current_a: 2.2, temp_c: 39.5, imu_accel_g: 0.16 }
    ],
    expected_model_torques_nm: [24.0, 67.0, 44.0, 16.5, 17.2, 7.8],
    tcp_speed_m_s: 1.10,
    vibration_window_g: [0.32, 0.38, 0.40, 0.35, 0.37]
  },
  nominal: {
    robot_id: "ROBOT-UR10E-CELL-04",
    joint_data: [
      { joint: 1, angle_cmd_deg: 25.0, angle_meas_deg: 25.01, torque_meas_nm: 20.5, current_a: 4.5, temp_c: 42.0, imu_accel_g: 0.16 },
      { joint: 2, angle_cmd_deg: -60.0, angle_meas_deg: -59.98, torque_meas_nm: 55.0, current_a: 9.8, temp_c: 52.0, imu_accel_g: 0.28 },
      { joint: 3, angle_cmd_deg: 85.0, angle_meas_deg: 84.99, torque_meas_nm: 36.0, current_a: 8.6, temp_c: 53.5, imu_accel_g: 0.25 },
      { joint: 4, angle_cmd_deg: -15.0, angle_meas_deg: -14.99, torque_meas_nm: 14.0, current_a: 3.5, temp_c: 40.0, imu_accel_g: 0.18 },
      { joint: 5, angle_cmd_deg: 30.0, angle_meas_deg: 30.01, torque_meas_nm: 15.0, current_a: 3.8, temp_c: 41.5, imu_accel_g: 0.20 },
      { joint: 6, angle_cmd_deg: 0.0, angle_meas_deg: 0.00, torque_meas_nm: 6.5, current_a: 1.8, temp_c: 36.0, imu_accel_g: 0.12 }
    ],
    expected_model_torques_nm: [20.0, 54.0, 35.0, 13.8, 14.7, 6.4],
    tcp_speed_m_s: 0.95,
    vibration_window_g: [0.22, 0.26, 0.28, 0.25, 0.24]
  }
};

let selectedScenario = 'critical_collision';
let payload;

if (body.joint_data && Array.isArray(body.joint_data)) {
  payload = body;
  selectedScenario = body.scenario || 'custom_payload';
} else if (body.scenario && SCENARIOS[body.scenario]) {
  selectedScenario = body.scenario;
  payload = SCENARIOS[body.scenario];
} else {
  payload = SCENARIOS.critical_collision;
}

// Compute Dynamics Residuals, Kinematic Tracking Errors, and Vibration RMS
const joints = payload.joint_data;
const DEFAULT_NOMINAL_TORQUES = [20.0, 55.0, 38.0, 15.0, 15.0, 7.0];
const expectedTorques = (payload.expected_model_torques_nm && payload.expected_model_torques_nm.length === 6)
  ? payload.expected_model_torques_nm
  : DEFAULT_NOMINAL_TORQUES;
let maxTrackingErrorDeg = 0.0;
let maxTorqueResidualNm = 0.0;
let maxJointTempC = 0.0;
let maxJointCurrentA = 0.0;
let worstJointId = 1;

const enrichedJoints = joints.map((j, idx) => {
  const trackingError = Math.round(Math.abs(j.angle_cmd_deg - j.angle_meas_deg) * 1000) / 1000;
  const expectedT = expectedTorques[idx] ?? j.torque_meas_nm;
  const torqueResidual = Math.round(Math.abs(j.torque_meas_nm - expectedT) * 100) / 100;

  if (trackingError > maxTrackingErrorDeg) maxTrackingErrorDeg = trackingError;
  if (torqueResidual > maxTorqueResidualNm) {
    maxTorqueResidualNm = torqueResidual;
    worstJointId = j.joint;
  }
  if (j.temp_c > maxJointTempC) maxJointTempC = j.temp_c;
  if (j.current_a > maxJointCurrentA) maxJointCurrentA = j.current_a;

  return {
    ...j,
    tracking_error_deg: trackingError,
    torque_residual_nm: torqueResidual
  };
});

// Vibration acceleration RMS calculation: a_RMS = sqrt(1/N * sum(a^2))
const vibWindow = payload.vibration_window_g || [0.25, 0.30, 0.28];
const sumSq = vibWindow.reduce((acc, val) => acc + (val * val), 0);
const vibRmsG = Math.round(Math.sqrt(sumSq / vibWindow.length) * 100) / 100;

const computedMetrics = {
  max_tracking_error_deg: maxTrackingErrorDeg,
  max_torque_residual_nm: maxTorqueResidualNm,
  worst_affected_joint: worstJointId,
  max_joint_temp_c: maxJointTempC,
  max_joint_current_a: maxJointCurrentA,
  vibration_rms_g: vibRmsG,
  tcp_speed_m_s: payload.tcp_speed_m_s || 0.8
};

const agentPrompt = `ROBOT MULTI-AXIS TELEMETRY SNAPSHOT (Asset: ${payload.robot_id}):
Joint-by-Joint Telemetry:
${JSON.stringify(enrichedJoints, null, 2)}

PRE-CALCULATED MECHATRONIC METRICS:
- Max External Torque Residual: ${maxTorqueResidualNm} Nm (Worst Joint: Joint ${worstJointId})
- Max Kinematic Tracking Error: ${maxTrackingErrorDeg} °
- IMU Vibration RMS: ${vibRmsG} g
- Peak Joint Temperature: ${maxJointTempC} °C
- Peak Motor Current: ${maxJointCurrentA} A
- TCP Tool Center Point Speed: ${payload.tcp_speed_m_s} m/s

INSTRUCTIONS:
1. Apply ISO 10218-1 / ISO/TS 15066 safety rules and mechatronic failure mode criteria.
2. When an anomaly is detected (Critical or Warning), invoke the "Robotics ISO Safety & SOP Tool" with query 'COL' (collision), 'MEC' (harmonic wear), 'THM' (thermal), or 'ALL' to obtain the exact safety actuation sequence.
3. Return ONLY a valid JSON object matching the requested schema.`;

return [{
  json: {
    robot_asset_id: payload.robot_id || "ROBOT-UR10E-CELL-04",
    scenario: selectedScenario,
    joint_data: enrichedJoints,
    computed_metrics: computedMetrics,
    agent_input_prompt: agentPrompt,
    ingested_at: new Date().toISOString()
  }
}];

const protocols = {
  "SOP-ROB-COL-001": {
    title: "ISO/TS 15066 Biomechanical Collision Emergency Stop Sequence",
    standard: "ISO 10218-1 / IEC 60204-1 Category 0/1",
    action_sequence: [
      "Send hardware E-Stop interrupt via Safety Fieldbus (PROFIsafe / CIP Safety) within 15ms.",
      "Actuate electromechanical fail-safe friction brakes on Joints 1 through 6 (response time <= 35ms).",
      "De-energize servomotor PWM inverters (Safe Torque Off - STO, Cat 4 / PL-e).",
      "Broadcast ROS 2 message on topic /safety/emergency_stop with collision joint vector.",
      "Flash cell red beacon, sound audible 85dB alarm, and latch safety interlock requiring manual key reset."
    ]
  },
  "SOP-ROB-MEC-102": {
    title: "Harmonic Drive Gearbox Degradation & Bearing Pitting Overhaul",
    standard: "ISO 13849-1 Diagnostic Coverage High",
    action_sequence: [
      "Command controlled smooth deceleration to rest (IEC 60204-1 Category 1 Stop).",
      "Hold current trajectory position and lock mechanical brakes to avoid gravity sag.",
      "Lock out robot workcell for maintenance inspection.",
      "Perform grease degradation colorimetry and ferrographic particle analysis on harmonic flexspline.",
      "Measure backlash on Joint harmonic drive using dial test indicator (tolerance <= 0.04 deg)."
    ]
  },
  "SOP-ROB-THM-203": {
    title: "Closed-Loop Dynamic Velocity Scaling & Thermal Derating Protocol",
    standard: "VDI 2853 Industrial Robot Reliability",
    velocity_scaling: {
      speed_factor: 0.60,
      acceleration_derate_pct: 40,
      action: "Scale trajectory override speed to 60% and extend dwell pause by 1.8s between pick-and-place cycles."
    },
    cooling_protocol: [
      "Energize auxiliary joint forced-air convection fans on base and shoulder housings.",
      "Verify ambient enclosure thermal air-exchange filter status.",
      "Schedule preventive stator winding resistance check if temperature exceeds 80C on subsequent cycle."
    ]
  },
  "SOP-ROB-NOM-001": {
    title: "Routine Baseline Kinematic Surveillance",
    standard: "ISO 9283 Manipulating Industrial Robots Performance Criteria",
    action_sequence: ["Log 100Hz telemetry slice to SCADA historian.", "Update joint cumulative wear index."]
  }
};

const q = (typeof query !== 'undefined' && query) ? query.toString().toUpperCase() : 'ALL';
for (const k of Object.keys(protocols)) {
  if (q.includes(k) || (q.includes('COL') && k.includes('COL')) || (q.includes('MEC') && k.includes('MEC')) || (q.includes('THM') && k.includes('THM'))) {
    return JSON.stringify(protocols[k]);
  }
}
return JSON.stringify(protocols);

