// Robust Parser and Deterministic Robotics Safety Guardrail Fallback
const item = $input.first().json;
const rawOutput = item.output || item.text || JSON.stringify(item);
let upstreamMetrics = {};
try {
  upstreamMetrics = $('Kinematics & Telemetry Normalizer').first().json.computed_metrics || {};
} catch (e) {
  upstreamMetrics = item.computed_metrics || {};
}

let parsed = null;

// Clean markdown code fences if LLM wrapped output in ```json ... ```
try {
  let cleanStr = rawOutput.trim();
  if (cleanStr.startsWith('```')) {
    cleanStr = cleanStr.replace(/^```[a-zA-Z]*\n?/, '').replace(/\n?```$/, '').trim();
  }
  parsed = JSON.parse(cleanStr);
} catch (e) {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (err) {}
  }
}

// Deterministic Fail-Safe Safety Guardrail Fallback
if (!parsed || !parsed.severity) {
  const dTau = upstreamMetrics.max_torque_residual_nm ?? 0.0;
  const aRms = upstreamMetrics.vibration_rms_g ?? 0.25;
  const epsDeg = upstreamMetrics.max_tracking_error_deg ?? 0.01;
  const Tmax = upstreamMetrics.max_joint_temp_c ?? 45.0;
  const worstJ = upstreamMetrics.worst_affected_joint ?? 3;

  if (dTau > 70.0) {
    parsed = {
      severity: "Critical",
      iso_risk_tier: "Tier-1-Hazard",
      stop_category: "Cat-0-EStop",
      worst_affected_joint: worstJ,
      root_cause_hypothesis: `Deterministic guardrail triggered: External torque residual Δτ_ext = ${dTau} Nm exceeds ISO/TS 15066 safety threshold (70 Nm) on Joint ${worstJ}. Instantaneous collision E-Stop engaged.`,
      emergency_brake_sequence: [
        "Send hardware E-Stop interrupt via Safety Fieldbus (PROFIsafe / CIP Safety) within 15ms.",
        "Actuate electromechanical fail-safe friction brakes on Joints 1 through 6 (response time <= 35ms).",
        "De-energize servomotor PWM inverters (Safe Torque Off - STO, Cat 4 / PL-e).",
        "Broadcast ROS 2 message on topic /safety/emergency_stop with collision joint vector.",
        "Flash cell red beacon, sound audible 85dB alarm, and latch safety interlock requiring manual key reset."
      ],
      velocity_scaling: null,
      applicable_standard: "ISO 10218-1 / ISO/TS 15066 / IEC 60204-1"
    };
  } else if (aRms > 1.60 && epsDeg > 0.8) {
    parsed = {
      severity: "Critical",
      iso_risk_tier: "Tier-1-Hazard",
      stop_category: "Cat-1-ControlledStop",
      worst_affected_joint: worstJ,
      root_cause_hypothesis: `Deterministic guardrail triggered: High harmonic vibration acceleration a_RMS = ${aRms} g and tracking error ε_θ = ${epsDeg}° on Joint ${worstJ} indicates flexspline gear tooth pitting / wave generator bearing failure.`,
      emergency_brake_sequence: [
        "Command controlled smooth deceleration to rest (IEC 60204-1 Category 1 Stop).",
        "Hold current trajectory position and lock mechanical brakes to avoid gravity sag.",
        "Lock out robot workcell for maintenance inspection.",
        "Perform grease degradation colorimetry and backlash measurement with dial indicator."
      ],
      velocity_scaling: null,
      applicable_standard: "ISO 13849-1 PL-d / IEC 60204-1"
    };
  } else if (Tmax > 75.0) {
    parsed = {
      severity: "Warning",
      iso_risk_tier: "Tier-2-OperationalDeviation",
      stop_category: "Dynamic-Velocity-Derating",
      worst_affected_joint: worstJ,
      root_cause_hypothesis: `Deterministic guardrail triggered: Servomotor temperature T = ${Tmax} °C on Joint ${worstJ} exceeds thermal continuous threshold (75 °C). Initiating dynamic trajectory velocity derate.`,
      emergency_brake_sequence: [],
      velocity_scaling: {
        speed_factor: 0.60,
        target_joints: [worstJ],
        cooling_protocol: "Derate trajectory speed to 60% override and energize auxiliary joint air cooling fans."
      },
      applicable_standard: "VDI 2853 / ISO 13849-1"
    };
  } else {
    parsed = {
      severity: "Nominal",
      iso_risk_tier: "Tier-3-Nominal",
      stop_category: "None",
      worst_affected_joint: null,
      root_cause_hypothesis: "All 6 manipulator joints operate within nominal kinematic and dynamic envelopes.",
      emergency_brake_sequence: [],
      velocity_scaling: { speed_factor: 1.0, target_joints: [], cooling_protocol: "None" },
      applicable_standard: "ISO 9283"
    };
  }
}

// Normalize severity casing
let normSeverity = 'Nominal';
if (parsed.severity.toLowerCase().includes('crit')) normSeverity = 'Critical';
else if (parsed.severity.toLowerCase().includes('warn')) normSeverity = 'Warning';

return [{
  json: {
    ...item,
    severity: normSeverity,
    iso_risk_tier: parsed.iso_risk_tier || (normSeverity === 'Critical' ? 'Tier-1-Hazard' : normSeverity === 'Warning' ? 'Tier-2-OperationalDeviation' : 'Tier-3-Nominal'),
    stop_category: parsed.stop_category || (normSeverity === 'Critical' ? 'Cat-0-EStop' : normSeverity === 'Warning' ? 'Dynamic-Velocity-Derating' : 'None'),
    worst_affected_joint: parsed.worst_affected_joint || upstreamMetrics.worst_affected_joint || 1,
    root_cause_hypothesis: parsed.root_cause_hypothesis || 'Mechatronic diagnostic evaluation completed.',
    emergency_brake_sequence: parsed.emergency_brake_sequence || [],
    velocity_scaling: parsed.velocity_scaling || null,
    computed_metrics: upstreamMetrics,
    applicable_standard: parsed.applicable_standard || 'ISO 10218-1 / ISO/TS 15066 / IEC 60204-1',
    triage_timestamp: new Date().toISOString()
  }
}];

// Emergency Stop (Cat 0/1) & Safety Fieldbus Command Assembly
const item = $input.first().json;
const incidentId = `ESTOP-${Date.now().toString(36).toUpperCase()}-${Math.floor(Math.random() * 1000)}`;

const esdPayload = {
  incident_id: incidentId,
  timestamp: new Date().toISOString(),
  robot_asset_id: item.robot_asset_id || "ROBOT-UR10E-CELL-04",
  safety_action: "EMERGENCY_STOP_ACTUATION",
  stop_category: item.stop_category || "Cat-0-EStop",
  affected_joint: item.worst_affected_joint,
  functional_safety: {
    category: "ISO 13849-1 Category 4 / PL-e",
    safety_integrity_level: "IEC 62061 SIL-3",
    brake_actuation_time_budget_ms: 35
  },
  root_cause: item.root_cause_hypothesis,
  telemetry_snapshot: item.computed_metrics,
  actuation_commands: [
    { target: "FIELDBUS_SAFETY_BUS", command: "TRIP_STO_SAFE_TORQUE_OFF", latency_ms: 12 },
    { target: `JOINT_${item.worst_affected_joint}_BRAKE`, command: "CLAMP_MECHANICAL_FRICTION_BRAKE", latency_ms: 28 },
    { target: "ROS2_TOPIC_SAFETY_ESTOP", command: "PUBLISH_COLLISION_STATE", payload: { joint: item.worst_affected_joint, status: "TRIPPED" } },
    { target: "CELL_BEACON", command: "ACTUATE_RED_STROBE_AND_SIREN", mode: "CONTINUOUS" }
  ],
  emergency_brake_sequence: item.emergency_brake_sequence,
  pagerduty_incident: {
    summary: `[CRITICAL TIER-1] Robot Manipulator Safety E-Stop Triggered (${incidentId})`,
    urgency: "high",
    assigned_team: "Robotics Safety & Cell Maintenance Operations"
  }
};

return [{
  json: {
    ...item,
    action_type: "EMERGENCY_STOP_DISPATCH",
    dispatch_payload: esdPayload
  }
}];

// Dynamic Velocity Scaling & CMMS Predictive Maintenance Ticket Assembly
const item = $input.first().json;
const ticketId = `CMMS-ROB-${Date.now().toString(36).toUpperCase()}`;

const warningPayload = {
  ticket_id: ticketId,
  timestamp: new Date().toISOString(),
  robot_asset_id: item.robot_asset_id || "ROBOT-UR10E-CELL-04",
  safety_action: "DYNAMIC_TRAJECTORY_DERATING",
  stop_category: "Dynamic-Velocity-Derating",
  affected_joint: item.worst_affected_joint,
  functional_safety: {
    classification: "ISO 13849-1 Category 2 / PL-c",
    safety_level: "Operational Speed Limiting Mode"
  },
  root_cause: item.root_cause_hypothesis,
  telemetry_snapshot: item.computed_metrics,
  robot_controller_reconfiguration: {
    topic: "/robot_controller/trajectory_override",
    speed_factor: item.velocity_scaling?.speed_factor ?? 0.60,
    acceleration_derate_pct: 40,
    dwell_time_compensation_s: 1.8,
    forced_cooling_fan_override: "ON_MAX_FLOW"
  },
  cmms_maintenance_tasks: [
    `Inspect Joint ${item.worst_affected_joint} servomotor stator winding thermistor and thermal paste.`,
    "Verify heat sink cooling duct airflow and clear particulate intake filter.",
    "Conduct cycle time vs thermal dissipation telemetry review on cell controller."
  ]
};

return [{
  json: {
    ...item,
    action_type: "DYNAMIC_VELOCITY_DERATING_LOGGED",
    dispatch_payload: warningPayload
  }
}];

// Nominal Telemetry & MTBF Degradation Margin Heartbeat
const item = $input.first().json;

const nominalPayload = {
  heartbeat_id: `ROB-HB-${Date.now().toString(36).toUpperCase()}`,
  timestamp: new Date().toISOString(),
  robot_asset_id: item.robot_asset_id || "ROBOT-UR10E-CELL-04",
  operating_status: "NOMINAL_IN_CONTROL",
  mechatronic_health_margins: {
    torque_residual_margin_nm: Math.round((70.0 - (item.computed_metrics?.max_torque_residual_nm ?? 5.0)) * 10) / 10,
    vibration_margin_g: Math.round((1.60 - (item.computed_metrics?.vibration_rms_g ?? 0.25)) * 100) / 100,
    thermal_headroom_c: Math.round((75.0 - (item.computed_metrics?.max_joint_temp_c ?? 45.0)) * 10) / 10
  },
  root_cause: item.root_cause_hypothesis,
  next_scheduled_scan: new Date(Date.now() + 300000).toISOString()
};

return [{
  json: {
    ...item,
    action_type: "NOMINAL_HEARTBEAT_LOGGED",
    dispatch_payload: nominalPayload
  }
}];

// Comprehensive Robotics Diagnostics & Prognostics Report Generator
const triage = $('Parse & Validate Safety Triage').first().json;
const severity = triage.severity || 'Nominal';
const isoRiskTier = triage.iso_risk_tier || (severity === 'Critical' ? 'Tier-1-Hazard' : severity === 'Warning' ? 'Tier-2-OperationalDeviation' : 'Tier-3-Nominal');
const stopCat = triage.stop_category || (severity === 'Critical' ? 'Cat-0-EStop' : severity === 'Warning' ? 'Dynamic-Velocity-Derating' : 'None');

let metrics = {};
try {
  metrics = $('Kinematics & Telemetry Normalizer').first().json.computed_metrics || {};
} catch (e) {
  metrics = triage.computed_metrics || {};
}

let dispatchPayload = {};
try {
  if (severity === 'Critical') {
    dispatchPayload = $('Assemble Emergency Stop & ROS 2 Brake Command').first().json.dispatch_payload;
  } else if (severity === 'Warning') {
    dispatchPayload = $('Assemble Dynamic Velocity Scaling & CMMS Ticket').first().json.dispatch_payload;
  } else if (severity === 'Nominal') {
    dispatchPayload = $('Log Nominal SCADA Telemetry & MTBF Margin').first().json.dispatch_payload;
  }
} catch (e) {}

if (!dispatchPayload || Object.keys(dispatchPayload).length === 0) {
  const inp = $input.first()?.json;
